ern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "70b966db-058f-5c14-a5e5-efb09d54e299"}, {"title": "李克用请攻朱温，威言张浚朝相则夕至京", "start_year": 896, "end_year": 896, "time_original": "896年二月复相议后条；确日未载", "dynasty": "唐", "description": "李克用上表请发兵攻朱温，并称张浚早晨为相，自己晚上便到京师。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "496fd655-37d3-5b54-a35b-367cdb2366a7"}, {"title": "京师震惧，皇帝下诏和解复相争议", "start_year": 896, "end_year": 896, "time_original": "896年二月李克用表后；确日未载", "dynasty": "唐", "description": "京师震惧，唐昭宗下诏调解。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "878f67ac-a59f-571c-a4c3-631f1ed31aee"}, {"title": "天雄留后李继徽正式授节度使", "start_year": 896, "end_year": 896, "time_original": "896年三月；确日未载", "dynasty": "唐", "description": "朝廷以天雄留后李继徽为节度使。", "phases": [], "location_name": "天雄", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e5e5b1d7-6b2c-51aa-90cc-d324494e25a9"}]'::jsonb)
